use super::*;
use crate::{access::Workspace,catalog::AddProduct,restaurant_checkout::Menu};
const KEY:&str="0123456789abcdef0123456789abcdef0123456789abcdef0123456789abcdef";
const PASSWORD:&str="Synthetic restaurant password 2026";
fn seeded()->Workspace{let mut w=Workspace::new(Store::open(std::path::Path::new(":memory:"),KEY).unwrap());w.setup(PASSWORD).unwrap();w.add_product(AddProduct{operation_id:"pizza".into(),name:"Pizza".into(),sku:"PIZZA".into(),unit:"pcs".into(),unit_price_paise:10000,opening_stock_milli:10000}).unwrap();w.save_restaurant_menu(Menu{id:"menu".into(),product_id:"pizza".into(),category:"Food".into(),label:"Pizza".into(),variant:"Large".into(),available:true}).unwrap();w.hub_configure(true,None).unwrap();w}
fn connect(w:&mut Workspace)->(Value,String){let i=w.hub_admin().unwrap()["identity"].clone();let credential="a".repeat(64);
 let base=json!({"version":1,"hubId":i["hubId"],"businessId":i["businessId"],"deviceId":"phone","name":"Phone","credential":credential});w.hub_request("/v1/enrol","",base.clone()).unwrap();
 assert!(w.hub_request("/v1/session",&credential,json!({"version":1,"hubId":i["hubId"],"businessId":i["businessId"],"deviceId":"phone","username":"owner","password":PASSWORD})).is_err());
 let actor=w.local_session().unwrap().principal.id;w.hub_device("phone",1,Some(&actor)).unwrap();let session=w.hub_request("/v1/session",&credential,json!({"version":1,"hubId":i["hubId"],"businessId":i["businessId"],"deviceId":"phone","username":"owner","password":PASSWORD})).unwrap();(i,session["token"].as_str().unwrap().into())}
fn submission(w:&Workspace,i:&Value,id:&str)->Value{json!({"version":1,"hubId":i["hubId"],"businessId":i["businessId"],"actorId":w.local_session().unwrap().principal.id,"operationId":id,"orderId":"order","tableId":null,"expectedRevision":0,"items":[{"menuId":"menu","quantity":2,"expectedPricePaise":10000,"note":"No onion"}]})}
#[test]fn duplicate_acceptance_is_durable_and_never_posts_money_or_kot(){let mut w=seeded();let (i,t)=connect(&mut w);let request=submission(&w,&i,"operation");let a=w.hub_request("/v1/submit",&t,request.clone()).unwrap();assert_eq!(a["status"],"accepted");assert_eq!(w.hub_request("/v1/submit",&t,request.clone()).unwrap(),a);
 let mut conflict=request;conflict["items"][0]["quantity"]=json!(3);assert!(matches!(w.hub_request("/v1/submit",&t,conflict),Err(StoreError::OperationConflict)));
 for table in ["local_invoices","local_billing_ledger","local_restaurant_tickets"]{assert_eq!(w.store_for_test().0.query_row(&format!("SELECT count(*) FROM {table}"),[],|q|q.get::<_,i64>(0)).unwrap(),0);}
 w.hub_dispatch("operation",1).unwrap();w.hub_dispatch("operation",1).unwrap();assert_eq!(w.store_for_test().0.query_row("SELECT count(*) FROM local_restaurant_tickets",[],|q|q.get::<_,i64>(0)).unwrap(),1);
}
#[test]fn refused_payload_requires_new_identity_and_explicit_price_review(){let mut w=seeded();let(i,t)=connect(&mut w);let mut r=submission(&w,&i,"bad-price");r["items"][0]["expectedPricePaise"]=json!(9000);let a=w.hub_request("/v1/submit",&t,r.clone()).unwrap();assert_eq!(a["reason"],"price_changed_review_required");r["items"][0]["expectedPricePaise"]=json!(10000);assert!(w.hub_request("/v1/submit",&t,r.clone()).is_err());r["operationId"]=json!("accepted-price");assert_eq!(w.hub_request("/v1/submit",&t,r).unwrap()["status"],"accepted");}
#[test]fn stale_revision_and_revoked_devices_are_refused(){let mut w=seeded();let(i,t)=connect(&mut w);let r=submission(&w,&i,"first");w.hub_request("/v1/submit",&t,r).unwrap();let r=submission(&w,&i,"stale");assert_eq!(w.hub_request("/v1/submit",&t,r).unwrap()["reason"],"revision_conflict");w.hub_device("phone",2,None).unwrap();assert!(w.hub_request("/v1/workspace",&t,json!({"version":1,"hubId":i["hubId"],"businessId":i["businessId"]})).is_err());}
#[test]fn foreign_shop_and_unknown_status_never_create_an_order(){let mut w=seeded();let(i,t)=connect(&mut w);let mut r=submission(&w,&i,"foreign");r["businessId"]=json!("foreign");assert!(w.hub_request("/v1/submit",&t,r).is_err());let status=w.hub_request("/v1/operation",&t,json!({"version":1,"hubId":i["hubId"],"businessId":i["businessId"],"operationId":"never-sent"})).unwrap();assert_eq!(status["status"],"not_found");assert_eq!(w.store_for_test().0.query_row("SELECT count(*) FROM local_restaurant_orders",[],|q|q.get::<_,i64>(0)).unwrap(),0);}
